<template>
  <PageContainer>
    <div class="rooms-page">
      <header class="page-head"><div><h1>{{ t('rooms.title') }}</h1><p>{{ tr('Manage your room types, facilities, pricing, and interactive views.', '管理客房类型、设施、价格与交互视图。') }}</p></div><a-button v-perm="'mch:rooms:add'" type="primary" @click="openEditor(0, query.propertyId)"><PlusOutlined />{{ tr('Add New Room Type', '新增房型') }}</a-button></header>
      <div class="metrics"><article class="metric total"><div><span>{{ tr('Total Rooms', '客房总数') }}</span><HomeOutlined /></div><strong>{{ metrics.totalRooms }} {{ tr('Rooms', '间客房') }}</strong></article><article v-for="item in metrics.roomTypes" :key="item.id" class="metric"><div><span>{{ item.room_name }}</span><ApartmentOutlined /></div><strong>{{ item.base_stock }} {{ tr('Rooms', '间客房') }}</strong></article></div>
      <section class="toolbar"><a-input v-model:value="query.keyword" class="room-search" :placeholder="tr('Search room types...', '搜索房型…')" allow-clear @press-enter="search" /><a-select v-model:value="query.propertyId" :placeholder="t('rooms.filters.hotel')" allow-clear @change="search"><a-select-option v-for="hotel in hotels" :key="hotel.id" :value="hotel.id">{{ hotel.property_name }}</a-select-option></a-select><a-popover trigger="click" placement="bottomLeft"><template #content><div class="filter-panel"><label>{{ t('rooms.columns.saleStatus') }}</label><a-select v-model:value="query.status" allow-clear :placeholder="t('rooms.filters.status')" @change="search"><a-select-option :value="1">{{ t('rooms.status.active') }}</a-select-option><a-select-option :value="2">{{ t('rooms.status.inactive') }}</a-select-option></a-select><label>{{ t('rooms.columns.reviewStatus') }}</label><a-select v-model:value="query.reviewStatus" allow-clear :placeholder="t('rooms.filters.reviewStatus')" @change="search"><a-select-option v-for="(_, i) in reviewLabels" :key="i" :value="i">{{ reviewLabels[i] }}</a-select-option></a-select></div></template><a-button :type="query.status || query.reviewStatus !== undefined ? 'primary' : 'default'"><FilterOutlined />{{ tr('Filter', '筛选') }}</a-button></a-popover><a-select v-model:value="query.sort" :options="sortOptions" class="sort-select" @change="search" /><span class="result-count">{{ tr(`Showing ${list.length} of ${total} room types`, `显示 ${list.length} / ${total} 个房型`) }}</span></section>
      <a-spin :spinning="loading"><section class="rooms-panel"><a-result v-if="failed" status="error" :title="tr('Unable to load rooms', '房型加载失败')"><template #extra><a-button @click="loadList">{{ tr('Retry', '重试') }}</a-button></template></a-result><a-empty v-else-if="!list.length && !loading" :description="tr('No room types found', '暂无房型')" /><div class="room-grid"><article v-for="room in list" :key="room.id" class="room-card"><div class="cover"><img v-if="room.images?.[0]" :src="room.images[0]" :alt="room.room_name" /><HomeOutlined v-else class="empty-cover" /><span :class="['status-dot', { active: room.status === 1 && room.approved_version > 0 }]" :title="room.status === 1 && room.approved_version > 0 ? t('rooms.status.active') : t('rooms.status.inactive')" /><a-dropdown trigger="click"><button type="button" class="more" :aria-label="tr('More room actions', '更多房型操作')"><EllipsisOutlined /></button><template #overlay><a-menu><a-menu-item v-perm="'mch:rooms:add'" @click="copyRoom(room)"><CopyOutlined /> {{ tr('Copy as Draft', '复制为草稿') }}</a-menu-item><a-menu-item v-if="room.approved_version > 0" v-perm="'mch:rooms:status'" @click="toggleRoom(room)"><PoweroffOutlined /> {{ room.status === 1 ? t('rooms.status.inactive') : t('rooms.status.active') }}</a-menu-item><a-menu-item v-perm="'mch:rooms:delete'" danger @click="removeRoom(room)"><DeleteOutlined /> {{ tr('Delete / Request Delisting', '删除 / 申请下线') }}</a-menu-item></a-menu></template></a-dropdown></div><div class="room-body"><div class="room-name"><h2>{{ room.room_name }}</h2><span>{{ room.base_stock }} {{ tr('Rooms', '间') }}</span></div><p v-if="!query.propertyId" class="property-name">{{ room.property_name }}</p><div class="room-spec"><span><TeamOutlined />{{ room.max_guests }} {{ tr('Guests', '人') }}</span><span :title="bedLabel(room)"><ApartmentOutlined />{{ bedLabel(room) }}</span><span><ExpandOutlined />{{ areaLabel(room) }}</span></div><div class="room-price">{{ room.currency }} {{ Number(room.base_price).toLocaleString() }}<small> / {{ tr('night', '晚') }}</small></div><div class="review-line"><a-tag :color="reviewColor(room.review_status)">{{ reviewLabels[room.review_status] }}</a-tag><span class="stock-line"><span>{{ tr('Available today', '今日可售') }} {{ room.today_stock_left || 0 }}</span><span v-if="room.upcoming_stock_left != null" :class="['upcoming', { tight: upcomingTight(room) }]" :title="room.upcoming_stock_date ? `${tr('Lowest sellable in window', '窗口内最低可售')} ${room.upcoming_stock_date}` : ''">{{ upcomingLabel(room, tr) }}</span></span></div><p v-if="room.reject_reason" class="reject">{{ room.reject_reason }}</p><div class="card-actions"><a-button @click="openDetail(room.id, room.property_id)"><EyeOutlined />{{ tr('More Details', '更多详情') }}</a-button><a-button v-perm="'mch:rooms:edit'" type="primary" :disabled="room.review_status === 1" @click="openEditor(room.id, room.property_id)"><EditOutlined />{{ tr('Edit Room', '编辑客房') }}</a-button></div></div></article></div><a-pagination v-if="total > query.pageSize" :current="query.page" :page-size="query.pageSize" :total="total" show-size-changer :page-size-options="['9', '18', '36']" @change="changePage" /></section></a-spin>
      <RoomEditor v-if="editorOpen" :key="`edit-${editorId}`" :id="editorId" :property-id="modalPropertyId" @close="closeModal" @saved="saved" />
      <RoomDetail v-if="detailId" :key="`detail-${detailId}`" :id="detailId" :property-id="modalPropertyId" @close="closeModal" @edit="editFromDetail" @changed="loadList" />
    </div>
  </PageContainer>
</template>
<script setup lang="ts">
import { computed, onActivated, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { message, Modal } from 'ant-design-vue';
import { useI18n } from 'vue-i18n';
import { ApartmentOutlined, CopyOutlined, DeleteOutlined, EditOutlined, EllipsisOutlined, ExpandOutlined, EyeOutlined, FilterOutlined, HomeOutlined, PlusOutlined, PoweroffOutlined, TeamOutlined } from '@ant-design/icons-vue';
import PageContainer from '@/components/PageContainer.vue';
import { apiRoomCopy, apiRoomDelete, apiRoomHotels, apiRoomList, apiRoomToggleStatus, type MerchantRoom, type RoomHotelOption, type RoomMetrics } from '@/api/rooms';
import { useUserStore } from '@/stores/user';
import { areaLabel, bedLabel, upcomingLabel, upcomingTight, useRoomText } from './presentation';
import RoomEditor from './components/RoomEditor.vue';
import RoomDetail from './components/RoomDetail.vue';
const { t } = useI18n(); const tr = useRoomText(); const route = useRoute(); const router = useRouter(); const user = useUserStore();
const query = reactive({ page: 1, pageSize: 9, propertyId: (Number(route.query.propertyId) || user.selectedPropertyId || undefined) as number | undefined, keyword: '', status: undefined as number | undefined, reviewStatus: undefined as number | undefined, sort: 'updated' });
const loading = ref(false); const failed = ref(false); const hotels = ref<RoomHotelOption[]>([]); const list = ref<MerchantRoom[]>([]); const total = ref(0); const metrics = ref<RoomMetrics>({ totalRooms: 0, roomTypes: [] });
const editorOpen = ref(route.path.endsWith('/create') || route.path.endsWith('/edit')); const editorId = ref(editorOpen.value ? Number(route.params.id || 0) : 0); const detailId = ref(!editorOpen.value ? Number(route.params.id || 0) : 0); const modalPropertyId = ref(Number(route.query.propertyId) || 0); let requestVersion = 0;
const reviewLabels = computed(() => ['draft', 'pending', 'approved', 'rejected', 'withdrawn'].map(k => t(`rooms.review.${k}`)));
const sortOptions = computed(() => [{ value: 'updated', label: tr('Sort by: Latest', '排序：最近更新') }, { value: 'name', label: tr('Name', '房型名称') }, { value: 'priceAsc', label: tr('Price: Low to High', '价格：从低到高') }, { value: 'priceDesc', label: tr('Price: High to Low', '价格：从高到低') }, { value: 'quantity', label: tr('Room Quantity', '客房数量') }]);
function reviewColor(status: number) { return ['default', 'processing', 'success', 'error', 'default'][status]; }
async function loadList() { const version = ++requestVersion; loading.value = true; failed.value = false; try { const data = await apiRoomList({ ...query }); if (version !== requestVersion) return; list.value = data.list; total.value = data.total; metrics.value = data.metrics; } catch { if (version === requestVersion) { failed.value = true; list.value = []; } } finally { if (version === requestVersion) loading.value = false; } }
function search() { query.page = 1; void loadList(); }
function changePage(page: number, pageSize: number) { query.page = page; query.pageSize = pageSize; void loadList(); }
function openEditor(id: number, propertyId?: number) { editorId.value = id; modalPropertyId.value = propertyId || 0; editorOpen.value = true; }
function openDetail(id: number, propertyId: number) { detailId.value = id; modalPropertyId.value = propertyId; }
function editFromDetail(id: number, propertyId: number) { detailId.value = 0; openEditor(id, propertyId); }
function closeModal() { editorOpen.value = false; detailId.value = 0; if (route.path !== '/rooms') void router.replace({ path: '/rooms', query: query.propertyId ? { propertyId: query.propertyId } : {} }); }
async function saved(id: number, propertyId: number) { editorOpen.value = false; detailId.value = id; modalPropertyId.value = propertyId; await loadList(); }
async function copyRoom(room: MerchantRoom) { const result = await apiRoomCopy(room.id, room.property_id); message.success(t('rooms.messages.copied')); await loadList(); openEditor(result.id, room.property_id); }
async function toggleRoom(room: MerchantRoom) { await apiRoomToggleStatus(room.id, room.property_id); await loadList(); }
function removeRoom(room: MerchantRoom) { Modal.confirm({ title: t('rooms.actions.deleteConfirm'), content: room.room_name, onOk: async () => { const result = await apiRoomDelete(room.id, room.property_id); message.success(result.reviewRequired ? t('rooms.messages.deleteSubmitted') : t('rooms.messages.deleted')); await loadList(); } }); }
watch(() => user.selectedPropertyId, value => { query.propertyId = value || undefined; detailId.value = 0; search(); });
onMounted(async () => { hotels.value = await apiRoomHotels(); await loadList(); });
onActivated(() => { if (hotels.value.length) { query.propertyId = Number(route.query.propertyId) || user.selectedPropertyId || undefined; void loadList(); } });
</script>
<style scoped>
