cover;object-position:center}.empty-cover{font-size:46px;color:#cad3e8}.status-dot{position:absolute;left:12px;top:12px;width:11px;height:11px;border-radius:50%;background:#a4a9b5;border:2px solid #ffffff88;box-shadow:0 0 0 4px #ffffff25}.status-dot.active{background:#0dca67}.more{position:absolute;right:10px;top:10px;border:0;border-radius:6px;background:#ffffffec;font-size:20px;line-height:1;padding:5px;cursor:pointer}.room-body{padding:18px}.room-name{display:flex;justify-content:space-between;align-items:center;gap:8px}.room-name h2{margin:0;font-size:16px;font-weight:650;overflow-wrap:anywhere}.room-name>span{flex-shrink:0;font-size:11px;border-radius:12px;color:#858a94;background:#f0f1f4;padding:3px 7px}.property-name{font-size:11px;color:#9a9eab;margin:6px 0}.room-spec{display:flex;justify-content:space-between;gap:8px;margin:12px 0;font-size:11px;color:#90939c}.room-spec>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.room-spec .anticon{margin-right:4px}.room-price{font-size:17px;color:var(--room-primary);font-weight:600}.room-price small{font-size:11px;font-weight:400;color:#979ba6}.review-line{display:flex;align-items:center;justify-content:space-between;gap:6px;margin:12px 0;color:#9a9faa;font-size:10px}.review-line .ant-tag{font-size:10px;margin:0}.review-line .stock-line{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}.review-line .upcoming{color:#9a9faa}.review-line .upcoming.tight{color:#d9822b;font-weight:600}.reject{font-size:11px;color:#d95656;overflow-wrap:anywhere}.card-actions{display:flex;gap:8px;margin-top:16px}.card-actions>.ant-btn{flex:1;min-width:0;font-size:12px;padding-inline:6px}.rooms-panel>.ant-pagination{margin-top:24px;text-align:right}@media(max-width:1100px){.room-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.metric{min-width:210px}.toolbar :deep(.room-search){width:220px}}@media(max-width:650px){.page-head{align-items:flex-start;flex-direction:column;gap:12px}.room-grid{grid-template-columns:1fr}.rooms-panel{padding:12px}.metric{min-width:190px}.toolbar{padding:12px}.toolbar :deep(.room-search){width:100%}.result-count{margin-left:0;width:100%}.cover{height:210px}}
</style>
